    h, w = len(grid), len(grid[0])
    # The objects form a staircase when read from left to right. Each object
    # is moved to the prior object's lower-right corner, preserving its pixels.
    cells_by_color = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                cells_by_color.setdefault(v, []).append((r, c))
    objs = []
    for color, cells in cells_by_color.items():
        top = min(r for r, c in cells)
        left = min(c for r, c in cells)
        rel = [(r-top, c-left) for r, c in cells]
        bh = max(r for r, c in rel) + 1
        bw = max(c for r, c in rel) + 1
        objs.append((left, top, color, rel, bh, bw))
    objs.sort(key=lambda x: x[0])
    out = [[0] * w for _ in range(h)]
    top = left = 0
    for i, (_, original_top, color, rel, bh, bw) in enumerate(objs):
        if i == 0:
            top, left = original_top, objs[0][0]
        else:
            prev = objs[i-1]
            top += prev[4] - 1
            left += prev[5] - 1
        for dr, dc in rel:
            r, c = top + dr, left + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
    return out
